
/**
 * Event routes. Typed routes are regenerated by the dev server, so brand-new ones are not in the
 * generated union until it next runs; the strings are built here once instead of at every call site.
 */
export const eventHref = (slug: string) => `/events/${encodeURIComponent(slug)}` as never;
export const badgesHref = () => '/events/badges' as never;
export const eventsHref = () => '/events' as never;
export const counterHref = (slug: string, milestoneKey: string, taskKey: string) =>
  `/events/${encodeURIComponent(slug)}/counter?m=${encodeURIComponent(milestoneKey)}&t=${encodeURIComponent(taskKey)}` as never;
